UPDATE aircas_experiment A LEFT JOIN sys_program B ON A.program_id = B.program_id
SET A.status = #{dstStatus}, A.update_time = #{updateTime}
WHERE A.id = #{id} AND A.status = #{srcStatus} AND A.del_flag = '0' AND B.del_flag = '0'

UPDATE aircas_experiment A LEFT JOIN sys_program B ON A.program_id = B.program_id
SET A.status = #{dstStatus}, A.resource_id = #{resourceId}, A.update_time = #{updateTime}
WHERE A.id = #{id} AND A.status = #{srcStatus} AND A.del_flag = '0' AND B.del_flag = '0'

UPDATE aircas_experiment A LEFT JOIN sys_program B ON A.program_id = B.program_id
SET A.status = #{dstStatus}, A.stop_type = #{stopType}, A.update_time = #{updateTime}
WHERE A.id = #{id} AND A.status = #{srcStatus} AND A.del_flag = '0' AND B.del_flag = '0'

UPDATE aircas_experiment A LEFT JOIN sys_program B ON A.program_id = B.program_id
SET A.status = #{dstStatus}, A.update_time = #{updateTime}
WHERE A.id = #{id} AND A.status = #{srcStatus} AND A.del_flag = '0' AND B.del_flag = '0'

UPDATE aircas_experiment
SET del_flag = '1', mlflow_del = '0', update_time = #{updateTime}
WHERE program_id = #{programId} AND del_flag = '0'

UPDATE aircas_experiment
SET del_flag = '1', update_time = #{updateTime}
WHERE del_flag = '0' AND id IN

	#{id}

UPDATE aircas_experiment
SET mlflow_del = #{mlflowDel}, update_time = #{updateTime}
WHERE id = #{id} AND del_flag = '1'
